import { useState } from "react";
import { toast } from "sonner";
import recuperar from '../../../assets/recuperacion-de-cuenta.png'
import './RecuperarContrasenia.css'
import Boton from "../../Boton/Boton";

export default function RecuperarContrasenia({ onCerrar }) {
    const [correo, setCorreo] = useState('');
    const [cargando, setCargando] = useState(false);

    const enviar = async (e) => {
        e.preventDefault();
        setCargando(true);
        try {
            const resp = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/usuario/forgot`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ correo })
            });

            const data = await resp.json().catch(() => ({}));

            if (!resp.ok) {
                toast.error(data.message || "Error al enviar el correo.", { className: "__toaster_error" });
                return;
            }

            toast.success(data.message || "Correo enviado exitosamente.", { className: "__toaster_success" });
            setCorreo("");
            onCerrar();

        } catch (error) {
            console.log(error);
            toast.error("Error de conexión con el servidor.", { className: "__toaster_error" });
        }
        finally {
            setCargando(false);
        }
    };

    return (
        <div className="__recuperar_contenedor">

            {cargando && (
                <div className="__cargando_fondo">
                    <div className="__cargando"></div>
                </div>
            )}

            <h2 className="__titulo_recuperar">Recuperar contraseña</h2>

            <img
                src={recuperar}
                alt="Recuperar cuenta"
                className="__imagen_recuperar"
            />

            <form onSubmit={enviar} className="__form_recuperar">
                <input
                    type="email"
                    value={correo}
                    onChange={e => setCorreo(e.target.value)}
                    placeholder="Tu correo"
                    className="__input_recuperar"
                />

                <div style={{ display: "flex", justifyContent: "center" }}>
                    <Boton submit habilitado descripcion="Enviar Enlace" />
                </div>
            </form>
        </div>
    );
}
